import{_ as s,O as a,o as i,c as n,a as r,i as o,f as c}from"./chunks/framework.fmIt2z2h.js";const f=JSON.parse('{"title":"D.22　阶级、身份、不平等与社会排斥","description":"","frontmatter":{"title":"D.22　阶级、身份、不平等与社会排斥","xkChars":651,"xkLessons":{"D.22":{"title":"D.22　阶级、身份、不平等与社会排斥","lead":"收入、财富、控制权和承认不是同一资源；群体统计可以是真实的，却不能直接诊断成员的处境或解释差异原因。","explanation":["原文定位：第4869—4884行，原站定位/theory/appendix-d/d-22#section-d-22。本题切片及完整用户原稿均在source目录，可逐字回查。","短引文：“不能由一项身份类别直接诊断某个人处境。”收入是期间流量，财富是存量，现金缓冲影响临时应对；生产管理控制、资格、关系与承认又是其他资源。它们可能相关，也可能分离，不能用一个标签填满个人的全部机会。[T-main]","阶级阶层、污名边界、交叉性、精英再生产、殖民劳动、贫困流动提供不同问题入口。命名本身不证明群体有共同意志；但当标签实际进入雇主、服务规则或互动，它可以产生真实后果。研究者内部分类若从未到达这些环节，不能凭“被命名”就声称激活了同样作用。[T-main]","交叉性不等于身份数量或圈层图重叠，需要检查多套规则如何共同排除特定位置。统计交互是模型关系，制度交叉是规则如何联动，生活经验是当事处境与意义；三种材料互有联系，却不应以其中一种代替另外两种。[T-main]","教育流动必须分出生队列、报名、录取、毕业和后续机会。少数成功不证明所有入口开放；技能差异也不单独证明教学机会公平。反过来，选择障碍真实存在，不取消某人已获得技能的价值。控制精英要追准入、议程、资源和撤换，而非仅按职业学历贴标签。[T-main]","原文福利例是教学构造：被纳入统计者的地区平均收入可真实提高，但无证件者未进入统计和申请，覆盖主张须收窄。不能为了强调遗漏而删除已观察改善，也不能拿平均改善把缺席者当已受益。取证、交通、时间和照护成本是具体约束，不是品格或能力定论。[T-main]","资源成为个人机会还要时间、用途、控制和执行。家庭有钱不等于每位成员能决定和使用，企业资产也不等雇员可动用。承认、再分配和参与权分别回答被尊重、获得什么和能否影响规则，不能用其中一个替另外两个。[T-main]","具体测量参照：美国人口普查局2024年9月10日发布P60-282，以2023美元计报告2023住户收入中位数80610美元、较2022增4%；同页区分各组变化并说明税前货币口径不含实物转移。这不是每个美国人的可支配收入或财富，也没有据此识别造成组差的原因。[P-CENSUS]","该机构配套正文说明住户类别由拥有或租住住房的人界定。因此“某类住户中位数”并非逐个成员具有相同身份、资源、权限或体验的断言。本题新增观察点是统计单位与个人机会的断裂，而非把一份统计报告当制度已公平的证据。[P-CENSUS-GROUP]","相对差距和绝对差距需分别登记。低组与高组比值更接近1，同时金额差变大在数学上可以并存；究竟关心比例、绝对生活缺口、最低保障还是控制权，要公开目标，不能择有利指标宣布“不平等已解决”。[T-main]","正文连接§2.5提示证据与推论范围，§5.5.1核聚合，§9.7保留物质与意义条件，§10.5—10.8核重叠/权力/跨圈承接，第十四部分处理分配与责任。本题不将这些连接当个人身份评分工具。[T-main]","八个研究入口分别是22.01阶级阶层资本分布：查不同资源；22.02地位污名边界：查标签到达；22.03性别种族族群交叉性：查联动排除；22.04精英寡头再生产：查控制与撤换；22.05殖民奴隶制种族化劳动：保留具体历史通道而非群体本质；22.06贫困剥夺稀缺：列真实约束；22.07流动教育继承：逐阶段分母；22.08承认再分配共同生活：不把规范目标互相替代。这是本书研究导航，非这些领域的完整实证综述。[T-main]"],"argumentSteps":["列流量存量控制资格关系承认各资源，不以身份补未知。","追标签实际到达规则或互动的通道。","分交叉统计、制度联动与生活经验的证据任务。","核分组、阶段、遗漏位置及个人资源控制。","并报相对绝对指标及其规范目标，保留局部改善和覆盖缺口。"],"distinctions":[{"leftTitle":"住户收入","leftText":"住户单位的期间收入。","rightTitle":"个人机会","rightText":"还需控制用途时间与执行条件。"},{"leftTitle":"统计交互","leftText":"模型中的联合关系。","rightTitle":"制度交叉","rightText":"多规则怎样共同排除，需要机制材料。"},{"leftTitle":"组均值或中位数","leftText":"群体分布摘要。","rightTitle":"个人处境","rightText":"不能直接以群体值赋给成员。"},{"leftTitle":"相对差距缩小","leftText":"比值更接近1。","rightTitle":"绝对差距缩小","rightText":"金额差更小，是另一个比较。"}],"boundaries":["原文教学反例：平均收入提高但未纳入统计和申请者仍被遗漏。","教学反例：按住户类别中位数给某个个人配置收入与品格标签。","原文边界：研究者内部身份标签不自动到达雇主或服务规则。"],"questions":["组中位数能用来判断某个人吗？","相对差缩小是否绝对差也缩小？","没纳入者存在是否否定已观测改善？","标签有无效果取决什么？"],"diagramPath":"/reading-assets/S-D-22/figures/d22-resources.png","caseLinks":[{"title":"2024年发布的美国2023住户收入报告","href":"https://www.census.gov/library/publications/2024/demo/p60-282.html?os=win"}],"caseNotes":[{"title":"2024年发布的美国2023住户收入报告","text":"P60-282发布页报告2023住户收入中位数80610美元（2023美元），并说明税前货币、不含实物转移的口径；不同分组变化不一致。","sourceLabel":"U.S. Census Bureau: Income in the United States: 2023，P60-282","sourceUrl":"https://www.census.gov/library/publications/2024/demo/p60-282.html?os=win","sourceLocator":"2024-09-10发布页Introduction及Highlights第1—4项，网页202—212行；For More Information303—310行","boundary":"限定该历史版本与住户单位，不等个人资源控制、财富、当前最新收入或组差因果。","href":"https://www.census.gov/library/publications/2024/demo/p60-282.html?os=win"}],"sourceRefs":[{"section":"D.22","start_line":4869,"end_line":4884,"startLine":4869,"endLine":4884}],"outputId":"section-d-22","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","teachingExamples":[{"title":"教学构造：相对更近，绝对更远","text":"人工低组/高组从50/100变90/150。比值从0.5升0.6，向1靠近；绝对差从50变60，反而扩大。低组收入本身也从50升90。三项可同时真，不能只选一个宣布全部目标完成。","assumptions":"两组同单位同时间口径的虚构收入，无因果数据。","boundary":"不指真实身份群体，不推所有不平等指标同向。"},{"title":"教学构造：总资源不等于个人控制","text":"虚构两人家庭总额100，但一人可独立支配10，另一人控制90。总额100可以准确，不能据人均50说双方各可自由使用50；控制分布还需独立证据。","assumptions":"人工分配，不代表任何家庭或群体惯例。","boundary":"不凭家庭类型判断强制或责任。"}],"counterexamples":[{"identity":"constructed_boundary","text":"原文教学反例：平均收入提高但未纳入统计和申请者仍被遗漏。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"constructed_boundary","text":"教学反例：按住户类别中位数给某个个人配置收入与品格标签。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原文边界：研究者内部身份标签不自动到达雇主或服务规则。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]}],"questionAnswers":[{"question":"组中位数能用来判断某个人吗？","answer":"不能直接赋值，需个人资源控制与具体证据。","basis":"单位与分布。"},{"question":"相对差缩小是否绝对差也缩小？","answer":"不必，50/100到90/150即反例。","basis":"两个目标。"},{"question":"没纳入者存在是否否定已观测改善？","answer":"不否定局部真实结果，但应收窄覆盖并追遗漏位置。","basis":"正反结果共存。"},{"question":"标签有无效果取决什么？","answer":"要核它实际进入哪项规则或互动及结果，内部标签不是自动处理。","basis":"通道。"}],"figures":[{"path":"/reading-assets/S-D-22/figures/d22-resources.png","alt":"收入财富缓冲控制资格关系承认分开，标签不填个人未知。","caption":"据D.22。"},{"path":"/reading-assets/S-D-22/figures/d22-statistics.png","alt":"2024Census报告为2023住户税前货币中位数，不能变个人控制权。","caption":"官方发布页指定口径，非当前收入估计。"},{"path":"/reading-assets/S-D-22/figures/d22-gaps.png","alt":"人工50/100到90/150，比值0.5到0.6、绝对差50到60。","caption":"教学构造。"}],"diagramBrief":"三图展示资源类别、统计到个人边界与相对绝对差的人工算例。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"本单元涉及方法判断，真实来源仅支持所列事实；图与教学构造分别保留其身份。"},"openQuestions":["未分析原始CPS微数据、完整PDF或群体差异因果。","研究入口不构成八领域原作已读或对个人处境的诊断。"],"taskId":"S-D-22","sources":[{"id":"T-main","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§D.22，第4869—4884行","claim_support":["资源、标签、交叉性、阶段分母、遗漏、相对绝对差与八入口。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"P-CENSUS","title":"U.S. Census Bureau: Income in the United States: 2023，P60-282","url":"https://www.census.gov/library/publications/2024/demo/p60-282.html?os=win","source_type":"primary","version_or_date":"2024-09-10；2023美元口径","locator":"2024-09-10发布页Introduction及Highlights第1—4项，网页202—212行；For More Information303—310行","claim_support":["2024年发布版本报告2023实质住户收入中位数80610美元（2023美元），较2022增加4%；不同住户类别变化并不一致，正文口径为税前货币收入不含实物转移。"],"limits":["本人读官方发布页指定段，未读整份PDF或微数据；这是该历史版本口径，不当2026最新收入或个人可支配额，不从组差推个人或原因。"],"access_status":"partially_read"},{"id":"P-CENSUS-GROUP","title":"U.S. Census Bureau: Median Income of Non-Hispanic White Households Increased While Asian, Black and Hispanic Median Household Income Did Not Change","url":"https://www.census.gov/library/stories/2024/09/household-income-race-hispanic.html","source_type":"primary","version_or_date":"2024-09-10正文；页面2026-07-20修改","locator":"2024-09-10正文，网页142—160行，尤其147行住户类别定义","claim_support":["文中住户类别按拥有或租住住房的某一人界定，不是对全体住户成员逐人收入的直接描述。"],"limits":["本人读正文，不报告更新提示所涉SPM贫困率；群体统计不证明个人能力、品格、歧视因果或共同意志。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-22/lecture.md","sourcesPath":"/reading-assets/S-D-22/sources.json","sourceSlicePath":"/reading-assets/S-D-22/source/S-D-22.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-22/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-22.md","filePath":"theory/appendix-d/d-22.md"}'),d={name:"theory/appendix-d/d-22.md"};function l(p,e,u,m,h,_){const t=a("SectionLesson");return i(),n("div",null,[e[0]||(e[0]=r('<div class="theory-source"><h1 id="section-d-22" tabindex="-1"><span class="xk-num"><span class="xk-num__n">D.22</span><span class="xk-num__gap">　</span></span>阶级、身份、不平等与社会排斥 <a class="header-anchor" href="#section-d-22" aria-label="Permalink to &quot;D.22　阶级、身份、不平等与社会排斥 {#section-d-22}&quot;">​</a></h1><p>正文连接：§2.5；§5.5.1；§9.7；§10.5—10.8；§14.4—14.5。研究入口：22.01—22.08。</p><p>收入、财富、现金缓冲、生产与管理控制、资格、社会关系和承认地位是不同资源。阶级与阶层研究、污名和社会边界、交叉性、精英再生产、殖民与劳动、贫困和流动各自指出可能的通道，不能由一项身份类别直接诊断某个人处境。</p><p>命名不证明已有共同意志，但命名可以经分类、服务资格、就业和互动产生真实作用。交叉性不仅是圈层重叠或身份数目，更要问几套规则怎样共同排除某一位置；统计交互、制度交叉与生活经验又须分别论证。一个群体平均改善与内部仍有排斥可以同时成立。</p><p>教育和社会流动须区分出生队列、报名、录取、毕业及后续机会。测到技能差异并不证明教学机会公平，观察到少数成功也不能代表全部制度开放。反过来，存在选择障碍不取消真实技能的价值。精英控制要追踪准入、议程、资源和撤换机制，不能仅凭学历或职业命名。</p><p>教学例：某项福利提高地区平均收入，但没有证件的人未被纳入统计和申请。平均结果可以保持真实，覆盖主张必须收窄并单列未进入者。贫困带来的时间、交通、照护与取证成本应作为具体约束，不转化成能力或品格定论；承认、再分配和参与权各有需要回答的问题。</p><p>资源成为个人机会需要时间、用途、控制与执行条件。家庭总量、企业资产或群体均值可以回答总量问题，却不能直接给个人配置控制权和福利。身份标签的效应须经实际到达雇主、服务规则或互动过程的通道；研究者内部标签不自动激活这些后果。相对差距缩小与绝对差距扩大也可同时成立，须分别说明比较目标。</p><p>专题定位：22.01 阶级、阶层与资本分布；22.02 地位、污名与社会边界；22.03 性别、种族、族群与交叉性；22.04 精英、寡头与权力再生产；22.05 殖民、奴隶制与种族化劳动；22.06 贫困、剥夺与稀缺；22.07 社会流动、教育与继承；22.08 承认、再分配与共同生活。</p></div>',1)),o(t,{section:"D.22"}),e[1]||(e[1]=c("div",{class:"theory-source"},null,-1))])}const b=s(d,[["render",l]]);export{f as __pageData,b as default};
